const D = { energy:.5, scale:1, hue:330, shape:.0, glow:.7, flicker:.3, thick:.5, x:.5, y:.45, speed:1, density:.5, style:'pink', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const sty=P.style, en=P.energy, t=K.t, dc=drawingContext, TAU=Math.PI*2;
const u=Math.min(width,height), sc=u*0.0020*P.scale, cx=P.x*width, cy=P.y*height;
// soft buzz flicker (NOT strobe): occasional dip, mostly steady
const buzz = 1 - (fr(Math.floor(t*8))<0.06*P.flicker ? (0.4+0.4*fr(Math.floor(t*8)+1)) : 0) - 0.05*Math.sin(t*30)*P.flicker;
const glowP = (0.55+0.45*(0.5+0.5*Math.sin(t*0.43)+0.3*Math.sin(t*0.91+1))) * buzz;
const kick=K.pulse*0.2+A.bass*0.3;

let tube=[P.hue,90,100], tube2=[(P.hue+40)%360,90,100];
if(sty==='blue'){ tube=[200,90,100]; tube2=[190,80,100]; }
else if(sty==='multi'){ tube=[P.hue,90,100]; tube2=[(P.hue+140)%360,90,100]; }
else if(sty==='warm'){ tube=[38,60,100]; tube2=[30,55,100]; }
else if(sty==='green'){ tube=[140,85,100]; tube2=[160,80,100]; }
function tubeCol(a){ return color(a[0],a[1],a[2]); }

// choose a shape path from P.shape (0 heart,1 star,2 arrow,3 lightning,4 cocktail,5 ring)
const sh=Math.min(5,Math.floor(P.shape*5.999));
function pathHeart(){ const pts=[]; for(let i=0;i<=40;i++){ const a=i/40*TAU; const x=16*Math.pow(Math.sin(a),3); const y=-(13*Math.cos(a)-5*Math.cos(2*a)-2*Math.cos(3*a)-Math.cos(4*a)); pts.push([x*2.6,y*2.6]);} return [pts]; }
function pathStar(){ const pts=[]; for(let i=0;i<=10;i++){ const a=-Math.PI/2+i/10*TAU; const r=(i%2?18:44); pts.push([Math.cos(a)*r,Math.sin(a)*r]);} return [pts]; }
function pathArrow(){ return [[[-46,0],[24,0]],[[24,0],[4,-18]],[[24,0],[4,18]]]; }
function pathBolt(){ return [[[-8,-46],[-22,4],[-2,4],[-14,46],[26,-10],[4,-10],[16,-46],[-8,-46]]]; }
function pathCocktail(){ return [[[-30,-30],[30,-30],[2,4],[2,40]],[[-16,40],[20,40]],[[24,-40],[6,-16]]]; }
function pathRing(){ const pts=[]; for(let i=0;i<=40;i++){ const a=i/40*TAU; pts.push([Math.cos(a)*40,Math.sin(a)*40]);} return [pts]; }
const paths=[pathHeart,pathStar,pathArrow,pathBolt,pathCocktail,pathRing][sh]();

push();
const swingA=Math.sin(t*0.5)*0.06+Math.sin(t*1.13+0.7)*0.03;
translate(cx+Math.sin(t*0.4+1)*12*sc, cy+Math.sin(t*0.83)*5*sc);
rotate(swingA);
scale(sc);
// mounting board (dim) behind
noStroke(); fill(color(0,0,8, 30*P.alpha/100)); rect(-70,-70,140,140,10);
// breathing colour halo cast on the surroundings (large soft area -> carries motion)
dc.save(); blendMode(ADD);
const hb=(0.35+0.55*glowP);
const halo=dc.createRadialGradient(0,0,4,0,0,150);
halo.addColorStop(0, color(tube[0],tube[1]*0.7,100, 26*hb*P.glow*P.alpha/100).toString());
halo.addColorStop(0.5, color(tube[0],tube[1],90, 10*hb*P.glow*P.alpha/100).toString());
halo.addColorStop(1, color(tube[0],tube[1],90,0).toString());
dc.fillStyle=halo; dc.fillRect(-170,-170,340,340); dc.restore(); blendMode(BLEND);
// marquee chasing bulbs around the border (classic sign — guaranteed motion)
dc.save(); blendMode(ADD);
const nb=Math.floor(22+P.density*18);
for(let i=0;i<nb;i++){ const a=i/nb*TAU; const bx=Math.cos(a)*86, by=Math.sin(a)*86;
  const chase=(Math.sin((i/nb - t*(0.25+en*0.35)*P.speed)*TAU)*0.5+0.5);
  if(chase>0.35){ dc.shadowBlur=8*chase*P.glow; dc.shadowColor=tubeCol(tube).toString(); }
  fill(color(tube[0],tube[1]*0.45,100, (22+chase*70)*P.alpha/100)); circle(bx,by, 3.5+chase*3.5); dc.shadowBlur=0; }
dc.restore(); blendMode(BLEND);
// draw glow (blurred) then bright core
const w=(4+P.thick*8);
for(let pass=0;pass<2;pass++){
  const bright= pass===0; // pass0 = wide glow, pass1 = core
  dc.save();
  if(bright){ blendMode(ADD); dc.shadowBlur=(18+P.glow*30)*glowP; dc.shadowColor=tubeCol(tube).toString(); }
  noFill();
  for(let pi=0; pi<paths.length; pi++){ const pts=paths[pi];
    const c = (pi%2===0)? tube : (sty==='multi'?tube2:tube);
    stroke(color(c[0],c[1],c[2], (bright? 30+50*glowP : 100)*P.alpha/100 ));
    strokeWeight( bright ? w*2.4 : w );
    strokeJoin(ROUND); strokeCap(ROUND);
    beginShape(); for(const p of pts) vertex(p[0],p[1]); endShape(pi===0&&(sh===0||sh===1||sh===5)?CLOSE:undefined); }
  dc.restore();
}
blendMode(BLEND); dc.shadowBlur=0;
// tiny mounting bolts
fill(color(0,0,40,60*P.alpha/100)); noStroke(); circle(-60,-60,5); circle(60,-60,5); circle(-60,60,5); circle(60,60,5);
pop();
